<?php require_once '../includes/functions.php';require_user();$uid=user()['id'];if(isset($_GET['add'])){$id=(int)$_GET['add'];$s=$pdo->prepare('SELECT id FROM places WHERE id=?');$s->execute([$id]);if($s->fetch()){$pdo->prepare('INSERT INTO trips(user_id,place_id,trip_date,people,budget) VALUES(?,?,CURDATE(),1,0)')->execute([$uid,$id]);$_SESSION['flash']='Destination added to your trip plan.';}redirect('user/trips.php');}if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM trips WHERE id=? AND user_id=?')->execute([(int)$_GET['delete'],$uid]);redirect('user/trips.php');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('INSERT INTO trips(user_id,place_id,trip_date,people,budget,notes) VALUES(?,?,?,?,?,?)')->execute([$uid,(int)$_POST['place_id'],$_POST['trip_date'],max(1,(int)$_POST['people']),(float)$_POST['budget'],trim($_POST['notes'])]);redirect('user/trips.php');}$s=$pdo->prepare('SELECT t.*,p.name,p.cover_image FROM trips t JOIN places p ON p.id=t.place_id WHERE t.user_id=? ORDER BY t.trip_date');$s->execute([$uid]);$trips=$s->fetchAll();$places=$pdo->query("SELECT id,name FROM places WHERE status='published' ORDER BY name")->fetchAll();$page_title='My Trip Plan';require '../includes/header.php';?><section class="section"><div class="section-heading"><div><h1>My Trip Plan</h1><p>Plan your dream trip and keep track of your journey.</p></div></div><form method="post" class="inline-form"><?=csrf_field()?><select name="place_id" required><option value="">Select destination</option><?php foreach($places as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select><input type="date" name="trip_date" required min="<?=date('Y-m-d')?>"><input type="number" name="people" min="1" value="1" placeholder="People"><input type="number" name="budget" min="0" placeholder="Budget (৳)"><input name="notes" placeholder="Notes (optional)"><button class="btn btn-primary">＋ Add Trip</button></form><div class="table-wrap"><table><thead><tr><th>Place</th><th>Date</th><th>People</th><th>Budget</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($trips as $t):?><tr><td><b><?=e($t['name'])?></b></td><td><?=e($t['trip_date'])?></td><td><?=$t['people']?></td><td><?=money($t['budget'])?></td><td><span class="status-pill"><?=strtotime($t['trip_date'])<strtotime('today')?'Completed':'Upcoming'?></span></td><td><a class="btn btn-danger btn-small" onclick="return confirm('Delete this trip?')" href="?delete=<?=$t['id']?>">Delete</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require '../includes/footer.php';?>
